pub(crate) trait ResidentStream: Read + Write + Send {
    fn set_resident_read_timeout(&self, timeout: Option<Duration>) -> io::Result<()>;
    fn set_resident_write_timeout(&self, timeout: Option<Duration>) -> io::Result<()>;
    fn set_resident_nonblocking(&self, nonblocking: bool) -> io::Result<()>;
    fn read_buffered_after_timeout_error(
        &mut self,
        _output: &mut [u8],
        _error: &io::Error,
        _deadline: Instant,
    ) -> Option<io::Result<usize>> {
        None
    }
    fn flush_after_timeout_error(
        &mut self,
        _error: &io::Error,
        _deadline: Instant,
    ) -> Option<io::Result<()>> {
        None
    }
    fn try_read_available(&mut self, output: &mut [u8]) -> io::Result<usize> {
        self.set_resident_nonblocking(true)?;
        let result = self.read(output);
        let restore = self.set_resident_nonblocking(false);
        match (result, restore) {
            (Err(error), Ok(())) if error.kind() == io::ErrorKind::WouldBlock => Ok(0),
            (result, Ok(())) => result,
            (_, Err(error)) => Err(error),
        }
    }
    fn configure_low_latency(&self) -> io::Result<()> {
        Ok(())
    }
}

impl ResidentStream for TcpStream {
    fn set_resident_read_timeout(&self, timeout: Option<Duration>) -> io::Result<()> {
        TcpStream::set_read_timeout(self, timeout)
    }

    fn set_resident_write_timeout(&self, timeout: Option<Duration>) -> io::Result<()> {
        TcpStream::set_write_timeout(self, timeout)
    }

    fn set_resident_nonblocking(&self, nonblocking: bool) -> io::Result<()> {
        self.set_nonblocking(nonblocking)
    }

    fn configure_low_latency(&self) -> io::Result<()> {
        self.set_nodelay(true)
    }
}

#[cfg(unix)]
impl ResidentStream for UnixStream {
    fn set_resident_read_timeout(&self, timeout: Option<Duration>) -> io::Result<()> {
        UnixStream::set_read_timeout(self, timeout)
    }

    fn set_resident_write_timeout(&self, timeout: Option<Duration>) -> io::Result<()> {
        UnixStream::set_write_timeout(self, timeout)
    }

    fn set_resident_nonblocking(&self, nonblocking: bool) -> io::Result<()> {
        self.set_nonblocking(nonblocking)
    }

    #[cfg(target_os = "macos")]
    fn read_buffered_after_timeout_error(
        &mut self,
        output: &mut [u8],
        error: &io::Error,
        deadline: Instant,
    ) -> Option<io::Result<usize>> {
        use nix::sys::socket::{recv, MsgFlags};
        use std::os::fd::AsRawFd;

        closed_unix_peer_after_timeout_error(self, error)?;
        if Instant::now() >= deadline {
            return Some(Err(io::Error::from(io::ErrorKind::TimedOut)));
        }
        // Read only already available bytes or EOF. Do not change socket mode,
        // reuse an old blocking timeout, or wait for any further peer data.
        Some(recv(self.as_raw_fd(), output, MsgFlags::MSG_DONTWAIT).map_err(io::Error::from))
    }

    #[cfg(target_os = "macos")]
    fn flush_after_timeout_error(
        &mut self,
        error: &io::Error,
        deadline: Instant,
    ) -> Option<io::Result<()>> {
        closed_unix_peer_after_timeout_error(self, error)?;
        if Instant::now() >= deadline {
            return Some(Err(io::Error::from(io::ErrorKind::TimedOut)));
        }
        // UnixStream has no buffered writes: its actual flush is a no-op.
        // No request bytes are written again after the peer has closed.
        Some(Write::flush(self))
    }
}

#[cfg(target_os = "macos")]
fn closed_unix_peer_after_timeout_error(stream: &UnixStream, error: &io::Error) -> Option<()> {
    use nix::errno::Errno;
    use nix::poll::{poll, PollFd, PollFlags, PollTimeout};
    use std::os::fd::AsFd;

    // Darwin rejects socket timeout setters after a Unix peer closes, even
    // when its complete response remains buffered. EINVAL alone is insufficient:
    // independently require hangup on this same owned descriptor.
    if error.raw_os_error() != Some(Errno::EINVAL as i32) {
        return None;
    }
    let mut descriptors = [PollFd::new(stream.as_fd(), PollFlags::POLLIN)];
    if poll(&mut descriptors, PollTimeout::ZERO).ok()? != 1 {
        return None;
    }
    let events = descriptors[0].revents()?;
    if !events.contains(PollFlags::POLLHUP)
        || events.intersects(PollFlags::POLLERR | PollFlags::POLLNVAL)
    {
        return None;
    }
    Some(())
}

pub(crate) type BoxedResidentStream = Box<dyn ResidentStream>;

pub(crate) struct PendingRequest {
    pub(crate) stream: BoxedResidentStream,
    pub(crate) request_id: [u8; crate::FRAME_REQUEST_ID_BYTES],
    pub(crate) request_digest: [u8; crate::FRAME_DIGEST_BYTES],
    pub(crate) length: usize,
    pub(crate) payload_prefix: Vec<u8>,
    pub(crate) accepted_at: Instant,
}

pub(crate) fn constant_time_eq(left: &[u8], right: &[u8]) -> bool {
    if left.len() != right.len() {
        return false;
    }
    let mut difference = 0u8;
    for (left_byte, right_byte) in left.iter().zip(right) {
        difference |= left_byte ^ right_byte;
    }
    difference == 0
}

pub(crate) fn hmac_sha256(key: &[u8], label: &[u8], nonce: &[u8]) -> [u8; crate::AUTH_PROOF_BYTES] {
    const BLOCK_BYTES: usize = 64;
    let mut key_block = [0u8; BLOCK_BYTES];
    if key.len() > BLOCK_BYTES {
        let digest = Sha256::digest(key);
        key_block[..digest.len()].copy_from_slice(&digest);
    } else {
        key_block[..key.len()].copy_from_slice(key);
    }

    let mut inner_pad = [0x36u8; BLOCK_BYTES];
    let mut outer_pad = [0x5cu8; BLOCK_BYTES];
    for index in 0..BLOCK_BYTES {
        inner_pad[index] ^= key_block[index];
        outer_pad[index] ^= key_block[index];
    }

    let mut inner = Sha256::new();
    inner.update(inner_pad);
    inner.update(label);
    inner.update(nonce);
    let inner_digest = inner.finalize();

    let mut outer = Sha256::new();
    outer.update(outer_pad);
    outer.update(inner_digest);
    let digest = outer.finalize();
    let mut proof = [0u8; crate::AUTH_PROOF_BYTES];
    proof.copy_from_slice(&digest);
    proof
}

fn authenticate_resident_stream(
    stream: &mut dyn ResidentStream,
    token: &[u8; crate::AUTH_TOKEN_BYTES],
) -> Result<(), String> {
    stream
        .set_resident_read_timeout(Some(crate::AUTH_TIMEOUT))
        .map_err(|_| "native_resident_auth_timeout_failed".to_owned())?;
    stream
        .set_resident_write_timeout(Some(crate::AUTH_TIMEOUT))
        .map_err(|_| "native_resident_auth_timeout_failed".to_owned())?;
    let _ = stream.configure_low_latency();

    let mut nonce = [0u8; crate::AUTH_NONCE_BYTES];
    stream
        .read_exact(&mut nonce)
        .map_err(|_| "native_resident_auth_nonce_failed".to_owned())?;
    let server_proof = hmac_sha256(token, crate::SERVER_PROOF_LABEL, &nonce);
    stream
        .write_all(&server_proof)
        .map_err(|_| "native_resident_auth_proof_failed".to_owned())?;

    let mut client_proof = [0u8; crate::AUTH_PROOF_BYTES];
    stream
        .read_exact(&mut client_proof)
        .map_err(|_| "native_resident_auth_client_failed".to_owned())?;
    let expected = hmac_sha256(token, crate::CLIENT_PROOF_LABEL, &nonce);
    if !constant_time_eq(&client_proof, &expected) {
        return Err("native_resident_auth_rejected".into());
    }
    Ok(())
}

fn read_request_header(mut stream: BoxedResidentStream) -> Result<PendingRequest, String> {
    stream
        .set_resident_read_timeout(Some(crate::HEADER_TIMEOUT))
        .map_err(|_| "native_frame_timeout_failed".to_owned())?;
    let mut header = [0u8; crate::FRAME_HEADER_BYTES];
    stream
        .read_exact(&mut header)
        .map_err(|_| "native_frame_header_failed".to_owned())?;
    if !constant_time_eq(&header[..4], crate::REQUEST_MAGIC) {
        return Err("native_frame_version_mismatch".to_owned());
    }
    let mut request_id = [0u8; crate::FRAME_REQUEST_ID_BYTES];
    request_id.copy_from_slice(&header[4..4 + crate::FRAME_REQUEST_ID_BYTES]);
    let digest_start = 4 + crate::FRAME_REQUEST_ID_BYTES;
    let mut request_digest = [0u8; crate::FRAME_DIGEST_BYTES];
    request_digest.copy_from_slice(&header[digest_start..digest_start + crate::FRAME_DIGEST_BYTES]);
    let length = u32::from_be_bytes(
        header[crate::FRAME_HEADER_BYTES - 4..]
            .try_into()
            .map_err(|_| "native_frame_header_failed".to_owned())?,
    ) as usize;
    if length == 0 || length > crate::MAX_NATIVE_REQUEST_BYTES {
        return Err("native_request_too_large".to_owned());
    }
    Ok(PendingRequest {
        stream,
        request_id,
        request_digest,
        length,
        payload_prefix: Vec::new(),
        accepted_at: Instant::now(),
    })
}

fn write_bound_response(
    stream: &mut dyn ResidentStream,
    request_id: &[u8; crate::FRAME_REQUEST_ID_BYTES],
    response: &[u8],
) -> Result<(), String> {
    if response.is_empty() || response.len() > crate::MAX_NATIVE_RESPONSE_BYTES {
        return Err("native_response_too_large".to_owned());
    }
    stream
        .set_resident_write_timeout(Some(crate::RESPONSE_TIMEOUT))
        .map_err(|_| "native_frame_timeout_failed".to_owned())?;
    let digest = Sha256::digest(response);
    let mut header = Vec::with_capacity(crate::FRAME_HEADER_BYTES);
    header.extend_from_slice(crate::RESPONSE_MAGIC);
    header.extend_from_slice(request_id);
    header.extend_from_slice(&digest);
    header.extend_from_slice(&(response.len() as u32).to_be_bytes());
    stream
        .write_all(&header)
        .map_err(|error| crate::hardening::write_error(&error, "native_frame_write_failed"))?;
    stream
        .write_all(response)
        .map_err(|error| crate::hardening::write_error(&error, "native_frame_write_failed"))?;
    stream
        .flush()
        .map_err(|error| crate::hardening::write_error(&error, "native_frame_write_failed"))?;
    Ok(())
}

fn write_overload(pending: &mut PendingRequest) {
    let response = crate::resident_protocol::error_response("native_overloaded", true);
    let _ = write_bound_response(&mut *pending.stream, &pending.request_id, &response);
}

fn handle_pending_request(
    mut pending: PendingRequest,
    policy_store: Option<&crate::policy_store::PolicySnapshotStore>,
) {
    if crate::hardening::request_expired(pending.accepted_at) {
        let response =
            crate::resident_protocol::error_response("native_request_deadline_exceeded", true);
        let _ = write_bound_response(&mut *pending.stream, &pending.request_id, &response);
        return;
    }
    let _ = pending
        .stream
        .set_resident_read_timeout(Some(crate::PAYLOAD_TIMEOUT));
    let prefix_length = pending.payload_prefix.len();
    let mut request = vec![0u8; pending.length];
    request[..prefix_length].copy_from_slice(&pending.payload_prefix);
    let mut disposition = crate::resident_protocol::LifecycleDisposition::Continue;
    let response = if pending
        .stream
        .read_exact(&mut request[prefix_length..])
        .is_err()
    {
        crate::resident_protocol::error_response("native_frame_read_failed", false)
    } else {
        let digest = Sha256::digest(&request);
        if !constant_time_eq(&digest, &pending.request_digest) {
            crate::resident_protocol::error_response("native_request_digest_mismatch", false)
        } else {
            match catch_unwind(AssertUnwindSafe(|| {
                crate::observe_native_phase!(
                    ResidentEvaluate,
                    crate::resident_protocol::evaluate_resident_bytes_started(
                        &request,
                        policy_store,
                        pending.accepted_at,
                    )
                )
            })) {
                Ok(Ok(evaluation)) => {
                    disposition = evaluation.disposition;
                    evaluation.response
                }
                Ok(Err(reason)) => crate::resident_protocol::safe_error_response(&reason, false),
                Err(_panic) => {
                    crate::resident_protocol::error_response("native_runtime_panicked", false)
                }
            }
        }
    };
    if disposition == crate::resident_protocol::LifecycleDisposition::Shutdown {
        crate::managed_resident::request_shutdown();
    }
    let _ = write_bound_response(&mut *pending.stream, &pending.request_id, &response);
    if disposition == crate::resident_protocol::LifecycleDisposition::Shutdown {
        crate::managed_resident::shutdown_response_sent();
    }
}

fn spawn_workers<T, F>(count: usize, receiver: Receiver<T>, handler: F)
where
    T: Send + 'static,
    F: Fn(T) + Send + Sync + 'static,
{
    let receiver = Arc::new(Mutex::new(receiver));
    let handler = Arc::new(handler);
    for _ in 0..count {
        let receiver = Arc::clone(&receiver);
        let handler = Arc::clone(&handler);
        thread::spawn(move || loop {
            let next = match receiver.lock() {
                Ok(guard) => guard.recv(),
                Err(_) => return,
            };
            match next {
                Ok(item) => handler(item),
                Err(_) => return,
            }
        });
    }
}

pub(crate) fn start_resident_workers(
    token: Arc<[u8; crate::AUTH_TOKEN_BYTES]>,
    policy_store: Option<Arc<crate::policy_store::PolicySnapshotStore>>,
) -> SyncSender<BoxedResidentStream> {
    let (evaluation_sender, evaluation_receiver) =
        sync_channel::<PendingRequest>(crate::EVALUATION_QUEUE_CAPACITY);
    let evaluation_policy_store = policy_store.clone();
    spawn_workers(
        crate::EVALUATION_WORKERS,
        evaluation_receiver,
        move |pending| {
            handle_pending_request(pending, evaluation_policy_store.as_deref());
        },
    );

    let (authentication_sender, authentication_receiver) =
        sync_channel::<BoxedResidentStream>(crate::AUTH_QUEUE_CAPACITY);
    spawn_workers(
        crate::AUTH_WORKERS,
        authentication_receiver,
        move |mut stream| {
            if authenticate_resident_stream(&mut *stream, &token).is_err() {
                return;
            }
            let mut pending = match read_request_header(stream) {
                Ok(value) => value,
                Err(_) => return,
            };
            pending
                .payload_prefix
                .resize(pending.length.min(crate::AUTHENTICATED_PREFETCH_BYTES), 0);
            let available = match pending
                .stream
                .try_read_available(&mut pending.payload_prefix)
            {
                Ok(value) => value,
                Err(_) => return,
            };
            pending.payload_prefix.truncate(available);
            if available == pending.length {
                handle_pending_request(pending, policy_store.as_deref());
                return;
            }
            match evaluation_sender.try_send(pending) {
                Ok(()) => {}
                Err(TrySendError::Full(returned)) => {
                    let mut pending = returned;
                    write_overload(&mut pending);
                }
                Err(TrySendError::Disconnected(_returned)) => {}
            }
        },
    );
    authentication_sender
}

pub(crate) fn admit_connection(
    sender: &SyncSender<BoxedResidentStream>,
    stream: BoxedResidentStream,
) -> Result<(), String> {
    match sender.try_send(stream) {
        Ok(()) => Ok(()),
        Err(TrySendError::Full(_stream)) => Ok(()),
        Err(TrySendError::Disconnected(_stream)) => {
            Err("native_resident_worker_pool_stopped".to_owned())
        }
    }
}

#!/usr/bin/env python3
"""Prove Python hook ownership, oracle reachability, and package cleanup."""

from __future__ import annotations

import argparse
import json
import os
import subprocess
import sys
import tarfile
from hashlib import sha256
from pathlib import Path
from typing import Final
from zipfile import ZipFile

try:
    import tomllib
except ModuleNotFoundError:  # pragma: no cover - Python 3.10 compatibility
    import tomli as tomllib

_REPO_ROOT = Path(__file__).resolve().parents[2]
if str(_REPO_ROOT) not in sys.path:
    sys.path.insert(0, str(_REPO_ROOT))

from scripts.ci.python_capability_cleanup_analysis import (  # noqa: E402
    DynamicImport as _DynamicImport,
)
from scripts.ci.python_capability_cleanup_analysis import (  # noqa: E402
    _analyze_import_graph as _analyze_import_graph,
)
from scripts.ci.python_capability_cleanup_analysis import (  # noqa: E402, F401
    dynamic_import_destinations as _dynamic_import_destinations,
)
from scripts.ci.python_capability_cleanup_analysis import (  # noqa: E402, F401
    module_imports as _module_imports,
)
from scripts.ci.python_capability_cleanup_analysis import (  # noqa: E402
    module_name as _module_name,
)
from scripts.ci.python_capability_cleanup_analysis import (  # noqa: E402
    production_importers as _production_importers,
)
from scripts.ci.python_capability_cleanup_analysis import (  # noqa: E402
    reachable as _reachable,
)

SCHEMA: Final = "hol-guard.python-capability-cleanup.v1"
CONTRACT: Final = "docs/guard/contracts/python-capability-ownership.v1.json"
_ALLOWED_CLASSES: Final = frozenset({"required_control_plane", "named_reference_oracle", "dead_duplicate"})
_MAX_DYNAMIC_IMPORT_DESTINATION: Final = 256
_IMPORT_ROOTS: Final = (
    "codex_plugin_scanner.cli",
    "codex_plugin_scanner.guard.cli.commands",
    "codex_plugin_scanner.guard.daemon.server",
    "codex_plugin_scanner.guard.daemon.hook_process_entrypoint",
)


def _read_json(path: Path) -> dict[str, object]:
    value = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(value, dict):
        raise RuntimeError(f"expected JSON object: {path}")
    return value


def _paths(root: Path, patterns: list[str], excludes: list[str] | None = None) -> set[str]:
    excluded = {path for pattern in excludes or [] for path in root.glob(pattern) if path.is_file()}
    return {
        path.relative_to(root).as_posix()
        for pattern in patterns
        for path in root.glob(pattern)
        if path.is_file() and path not in excluded
    }


def _validate_contract(root: Path) -> tuple[dict[str, object], dict[str, str], set[str]]:
    contract = _read_json(root / CONTRACT)
    if contract.get("schema") != "hol-guard.python-capability-ownership.v1":
        raise RuntimeError("unexpected Python capability ownership schema")
    classes = contract.get("classes")
    if not isinstance(classes, list) or set(classes) != _ALLOWED_CLASSES:
        raise RuntimeError("ownership classes do not match the cleanup gate")
    scope_globs = contract.get("scope_globs")
    dynamic_import_policy = contract.get("dynamic_import_policy")
    if not isinstance(dynamic_import_policy, dict):
        raise RuntimeError("dynamic_import_policy must be an object")
    if dynamic_import_policy.get("mode") != "literal_or_bounded":
        raise RuntimeError("unsupported dynamic import policy")
    max_destination_length = dynamic_import_policy.get("max_destination_length")
    if max_destination_length != _MAX_DYNAMIC_IMPORT_DESTINATION:
        raise RuntimeError("dynamic import destination bound is out of sync")
    capabilities = contract.get("capabilities")
    if not isinstance(scope_globs, list) or not all(isinstance(item, str) for item in scope_globs):
        raise RuntimeError("scope_globs must be a list of strings")
    if not isinstance(capabilities, list) or not capabilities:
        raise RuntimeError("capabilities must be a non-empty list")
    scope = _paths(root, scope_globs)
    owners: dict[str, str] = {}
    for capability in capabilities:
        if not isinstance(capability, dict):
            raise RuntimeError("capability entries must be objects")
        capability_id = capability.get("id")
        capability_class = capability.get("class")
        patterns = capability.get("patterns")
        if not isinstance(capability_id, str) or not capability_id:
            raise RuntimeError("capability id is required")
        if capability_class not in _ALLOWED_CLASSES:
            raise RuntimeError(f"invalid class for {capability_id}: {capability_class}")
        if not isinstance(patterns, list) or not all(isinstance(item, str) for item in patterns):
            raise RuntimeError(f"patterns missing for {capability_id}")
        files = _paths(root, patterns, capability.get("exclude_patterns"))
        if not files:
            raise RuntimeError(f"capability has no files: {capability_id}")
        for path in files:
            previous = owners.get(path)
            if previous is not None:
                raise RuntimeError(f"capability overlap for {path}: {previous}, {capability_id}")
            owners[path] = capability_id
    missing = sorted(scope - set(owners))
    extra = sorted(set(owners) - scope)
    if missing or extra:
        raise RuntimeError(f"ownership coverage mismatch: missing={missing}, extra={extra}")
    return contract, owners, scope


def _pyproject_excludes(root: Path) -> list[str]:
    with (root / "pyproject.toml").open("rb") as stream:
        document = tomllib.load(stream)
    value = document.get("tool", {}).get("hatch", {}).get("build", {}).get("exclude", [])
    if not isinstance(value, list) or not all(isinstance(item, str) for item in value):
        raise RuntimeError("tool.hatch.build.exclude must be a list of strings")
    return value


def _artifact_contains(artifact: Path, package_name: str) -> bool:
    if artifact.name.endswith(".whl"):
        with ZipFile(artifact) as archive:
            return package_name in archive.namelist()
    if artifact.name.endswith(".tar.gz"):
        with tarfile.open(artifact, "r:gz") as archive:
            return any(name.endswith(f"/{package_name}") or name == package_name for name in archive.getnames())
    raise RuntimeError(f"unsupported package artifact: {artifact}")


def _validate_fixture(root: Path, relative: str) -> dict[str, object]:
    fixture = _read_json(root / relative)
    if fixture.get("schema") != "hol-guard.native-hook-parity.v1" or fixture.get("version") != 1:
        raise RuntimeError("invalid native hook parity fixture header")
    cases = fixture.get("cases")
    if not isinstance(cases, list) or not cases:
        raise RuntimeError("parity fixture must contain cases")
    ids: set[str] = set()
    allowed_actions = {"allow", "review", "block", "require-reapproval", "sandbox-required"}
    for case in cases:
        if not isinstance(case, dict):
            raise RuntimeError("parity fixture cases must be objects")
        required = {"id", "event", "input_class", "expected_action"}
        if set(case) != required:
            raise RuntimeError(f"parity case fields must be language-neutral: {case}")
        case_id = case["id"]
        if not isinstance(case_id, str) or not case_id or case_id in ids:
            raise RuntimeError("parity case ids must be unique non-empty strings")
        if case["event"] not in {"PreToolUse", "PostToolUse", "Unknown"}:
            raise RuntimeError(f"unsupported parity event: {case['event']}")
        if case["expected_action"] not in allowed_actions:
            raise RuntimeError(f"unsupported parity action: {case['expected_action']}")
        ids.add(case_id)
    return {"case_count": len(cases), "sha256": sha256((root / relative).read_bytes()).hexdigest()}


def _verify_import_surface(root: Path, oracle_modules: list[str], candidate_module: str) -> None:
    source = root / "src"
    clean_env = os.environ.copy()
    for key in (
        "HOL_GUARD_NATIVE",
        "HOL_GUARD_NATIVE_DIAGNOSTIC",
        "HOL_GUARD_PYTHON_ORACLE",
        "HOL_GUARD_TEST_MODE",
        "PYTEST_CURRENT_TEST",
    ):
        clean_env.pop(key, None)
    code = (
        "import sys; "
        "import codex_plugin_scanner.guard.cli.commands_support; "
        "loaded = set(sys.modules); "
        f"forbidden = {oracle_modules!r} + [{candidate_module!r}]; "
        "assert not (loaded & set(forbidden)), sorted(loaded & set(forbidden))"
    )
    completed = subprocess.run(
        [sys.executable, "-c", code],
        cwd=root,
        env={**clean_env, "PYTHONPATH": str(source)},
        capture_output=True,
        text=True,
        check=False,
    )
    if completed.returncode:
        detail = completed.stderr.strip() or completed.stdout.strip()
        raise RuntimeError(f"production import surface reached retired Python hook code: {detail}")


def _candidate_evidence(
    root: Path,
    candidate: str,
    owners: dict[str, str],
    capability_classes: dict[str, str],
    exclusions: list[str],
) -> tuple[str, dict[str, object]]:
    path = root / candidate
    if not path.is_file():
        raise RuntimeError(f"retained deletion candidate is missing: {candidate}")
    owner = owners.get(candidate)
    if owner is None or capability_classes.get(owner) != "dead_duplicate":
        raise RuntimeError(f"candidate is not classified as dead_duplicate: {candidate}")
    if candidate not in exclusions:
        raise RuntimeError(f"dead candidate is not excluded from Hatch builds: {candidate}")
    module = _module_name(root, path)
    importers = _production_importers(root, module)
    if importers:
        raise RuntimeError(f"dead candidate still has source import reachability: {candidate}: {importers}")
    return module, {
        "path": candidate,
        "module": module,
        "loc": len(path.read_text(encoding="utf-8").splitlines()),
        "source_importers": [],
        "package_excluded": True,
    }


def _capability_classes(contract: dict[str, object]) -> dict[str, str]:
    capabilities = contract.get("capabilities")
    if not isinstance(capabilities, list):
        raise RuntimeError("capabilities must be a list")
    return {
        capability["id"]: capability["class"]
        for capability in capabilities
        if isinstance(capability, dict)
        and isinstance(capability.get("id"), str)
        and isinstance(capability.get("class"), str)
    }


def _run_inputs(
    root: Path,
    contract: dict[str, object],
) -> tuple[list[str], list[str], list[str], str, list[str]]:
    excluded_candidates = contract.get("package_excluded_candidates")
    deletion_candidates = contract.get("deletion_candidates")
    oracle_tests = contract.get("oracle_tests")
    if (
        not isinstance(excluded_candidates, list)
        or not excluded_candidates
        or not all(isinstance(item, str) for item in excluded_candidates)
    ):
        raise RuntimeError("package_excluded_candidates must be a non-empty list")
    if not isinstance(deletion_candidates, list) or not deletion_candidates:
        raise RuntimeError("deletion candidates must be recorded")
    if not isinstance(oracle_tests, list) or not all(isinstance(item, str) for item in oracle_tests):
        raise RuntimeError("oracle_tests must be a list")
    missing_tests = [path for path in oracle_tests if not (root / path).is_file()]
    if missing_tests:
        raise RuntimeError(f"named oracle tests are missing: {missing_tests}")
    fixture_relative = contract.get("parity_fixture")
    if not isinstance(fixture_relative, str):
        raise RuntimeError("parity_fixture is required")
    return excluded_candidates, deletion_candidates, oracle_tests, fixture_relative, _pyproject_excludes(root)


def _candidate_records(
    root: Path,
    candidates: list[str],
    owners: dict[str, str],
    capability_classes: dict[str, str],
    exclusions: list[str],
) -> tuple[list[str], list[dict[str, object]]]:
    modules: list[str] = []
    evidence: list[dict[str, object]] = []
    for candidate in candidates:
        module, item = _candidate_evidence(root, candidate, owners, capability_classes, exclusions)
        modules.append(module)
        evidence.append(item)
    return modules, evidence


def _validate_artifact_exclusions(root: Path, wheel: Path | None, candidates: list[str]) -> None:
    if wheel is None:
        return
    for candidate in candidates:
        package_name = candidate.removeprefix("src/")
        if _artifact_contains(wheel, package_name):
            raise RuntimeError(f"package artifact contains excluded dead module: {package_name}")


def _source_analysis(
    root: Path,
    owners: dict[str, str],
) -> tuple[dict[str, int], int, list[_DynamicImport], list[str]]:
    source_loc: dict[str, int] = {}
    for path, capability_id in owners.items():
        source_loc[capability_id] = source_loc.get(capability_id, 0) + len(
            (root / path).read_text(encoding="utf-8").splitlines()
        )
    import_graph, _dynamic, dynamic_imports, dynamic_unbounded = _analyze_import_graph(root)
    if dynamic_unbounded:
        raise RuntimeError(
            "dynamic import destination is not literal or statically bounded: " + ", ".join(sorted(dynamic_unbounded))
        )
    return source_loc, len(_reachable(_IMPORT_ROOTS, import_graph)), dynamic_imports, dynamic_unbounded


def _dynamic_import_evidence(dynamic_imports: list[_DynamicImport]) -> list[dict[str, object]]:
    return [
        {
            "module": item.module,
            "line": item.line,
            "destination_kind": item.destination_kind,
            "destination_count": item.destination_count,
        }
        for item in dynamic_imports
    ]


def run(root: Path, wheel: Path | None = None) -> dict[str, object]:
    root = root.resolve()
    contract, owners, scope = _validate_contract(root)
    capability_classes = _capability_classes(contract)
    excluded_candidates, _deletion_candidates, _oracle_tests, fixture_relative, exclusions = _run_inputs(root, contract)
    fixture = _validate_fixture(root, fixture_relative)
    candidate_modules, candidate_evidence = _candidate_records(
        root,
        excluded_candidates,
        owners,
        capability_classes,
        exclusions,
    )
    oracle_modules = contract.get("lazy_oracle_modules", [])
    if not isinstance(oracle_modules, list) or not all(isinstance(item, str) for item in oracle_modules):
        raise RuntimeError("lazy_oracle_modules must be a list")
    _verify_import_surface(root, oracle_modules, candidate_modules[0])
    _validate_artifact_exclusions(root, wheel, excluded_candidates)
    source_loc, reached, dynamic_imports, dynamic_unbounded = _source_analysis(root, owners)
    return {
        "schema": SCHEMA,
        "status": "passed",
        "slice": contract.get("slice"),
        "scope_files": len(scope),
