from . import update_commands as _update  # noqa: E402

"""Strict redacted native extension evidence and receipt binding validation."""

from __future__ import annotations

import hashlib
import json
import re
from typing import cast

_DIGEST = re.compile(r"[0-9a-f]{64}")
_CATALOG_ID = re.compile(r"command\.[a-z0-9]+(?:[.-][a-z0-9]+)*")
_VERSION = re.compile(r"[1-9][0-9]*\.[0-9]+\.[0-9]+")
_VARIANT = re.compile(r"[a-z0-9][a-z0-9_.:-]{0,255}")
_EXECUTABLE = re.compile(r"[A-Za-z0-9][A-Za-z0-9._+-]{0,127}")
_DETAIL = "Matched bounded structured command constraints."
_MAX_OBSERVATIONS = 2_048
_MAX_EVIDENCE = 8_192
_BINDING_FIELDS = frozenset(
    {
        "schema",
        "program_digest",
        "catalog_digest",
        "trust_digest",
        "control_revision",
        "managed_control_revision",
        "control_effective_digest",
        "observations_digest",
        "observation_count",
        "uncertainty_count",
    }
)
_OBSERVATION_FIELDS = frozenset(
    {
        "extension_id",
        "extension_version",
        "rule_id",
        "rule_version",
        "match_class",
        "match_classes",
        "matcher_evidence",
        "safe_variants",
        "uncertainty_reasons",
        "effective_segment_indexes",
    }
)


def _matches(value: object, pattern: re.Pattern[str], maximum: int) -> bool:
    return isinstance(value, str) and len(value) <= maximum and pattern.fullmatch(value) is not None


def _integer(value: object, maximum: int) -> bool:
    return type(value) is int and 0 <= value <= maximum


def valid_native_command_receipt_binding(value: object) -> bool:
    if not isinstance(value, dict) or set(value) != _BINDING_FIELDS:
        return False
    if value["schema"] != "guard.native-command-receipt-binding.v1":
        return False
    if any(
        not _matches(value[key], _DIGEST, 64)
        for key in (
            "program_digest",
            "catalog_digest",
            "trust_digest",
            "control_effective_digest",
            "observations_digest",
        )
    ):
        return False
    return (
        _integer(value["control_revision"], 2**64 - 1)
        and _integer(value["managed_control_revision"], 2**64 - 1)
        and _integer(value["observation_count"], _MAX_OBSERVATIONS)
        and _integer(value["uncertainty_count"], _MAX_OBSERVATIONS + 1)
    )


def _evidence_indexes(value: object, budget: list[int]) -> list[int] | None:
    if not isinstance(value, list) or len(value) > _MAX_EVIDENCE:
        return None
    budget[0] -= len(value)
    if budget[0] < 0:
        return None
    indexes: list[int] = []
    for item in value:
        if not isinstance(item, dict) or set(item) != {"segment_index", "executable", "detail"}:
            return None
        if not _integer(item["segment_index"], 127) or item["detail"] != _DETAIL:
            return None
        if item["executable"] is not None and not _matches(item["executable"], _EXECUTABLE, 128):
            return None
        indexes.append(cast(int, item["segment_index"]))
    return indexes


def _valid_observation(value: object, budget: list[int]) -> bool:
    if not isinstance(value, dict) or set(value) != _OBSERVATION_FIELDS:
        return False
    if any(not _matches(value[key], _CATALOG_ID, 256) for key in ("extension_id", "rule_id")):
        return False
    if not str(value["rule_id"]).startswith(f"{value['extension_id']}."):
        return False
    if any(not _matches(value[key], _VERSION, 64) for key in ("extension_version", "rule_version")):
        return False
    base = _evidence_indexes(value["matcher_evidence"], budget)
    variants = value["safe_variants"]
    uncertainty = value["uncertainty_reasons"]
    if base is None or not isinstance(variants, list) or len(variants) > 64:
        return False
    if uncertainty not in ([], ["matcher-failure"]):
        return False
    expected_classes = ["unsafe"] if base else []
    if uncertainty:
        expected_classes.append("uncertainty")
    if value["match_classes"] != expected_classes or value["match_class"] != (
        "uncertainty" if uncertainty else "unsafe"
    ):
        return False
    if not expected_classes or (not base and variants):
        return False
    variant_ids: set[str] = set()
    safe_indexes: set[int] = set()
    for variant in variants:
        if not isinstance(variant, dict) or set(variant) != {"match_class", "variant_id", "matcher_evidence"}:
            return False
        if variant["match_class"] != "safe-variant" or not _matches(variant["variant_id"], _VARIANT, 256):
            return False
        variant_id = cast(str, variant["variant_id"])
        if variant_id in variant_ids:
            return False
        variant_ids.add(variant_id)
        indexes = _evidence_indexes(variant["matcher_evidence"], budget)
        if not indexes:
            return False
        safe_indexes.update(indexes)
    effective = value["effective_segment_indexes"]
    if not isinstance(effective, list) or any(not _integer(index, 127) for index in effective):
        return False
    return effective == [index for index in base if index not in safe_indexes]


def _valid_permission_observation(value: object, budget: list[int]) -> bool:
    fields = {"extension_id", "permission_id", "matcher_evidence", "uncertainty_reasons"}
    if not isinstance(value, dict) or set(value) != fields:
        return False
    if not _matches(value["extension_id"], _CATALOG_ID, 256):
        return False
    permission_id = value["permission_id"]
    if not isinstance(permission_id, str) or len(permission_id) > 256:
        return False
    prefix = f"{value['extension_id']}.permission."
    if not permission_id.startswith(prefix) or not _matches(permission_id, _CATALOG_ID, 256):
        return False
    evidence = _evidence_indexes(value["matcher_evidence"], budget)
    uncertainty = value["uncertainty_reasons"]
    return evidence is not None and uncertainty in ([], ["matcher-failure"]) and bool(evidence or uncertainty)


def validate_native_command_observations(value: object) -> dict[str, object] | None:
    fields = {"schema", "binding", "observations", "permission_observations", "evaluation_error"}
    if not isinstance(value, dict) or set(value) != fields:
        return None
    if value["schema"] != "guard.native-command-observations.v1" or not valid_native_command_receipt_binding(
        value["binding"]
    ):
        return None
    observations = value["observations"]
    permission_observations = value["permission_observations"]
    error = value["evaluation_error"]
    if not isinstance(observations, list) or not isinstance(permission_observations, list):
        return None
    count = len(observations) + len(permission_observations)
    if count > _MAX_OBSERVATIONS:
        return None
    if error is not None and (error != "native_command_evaluation_failed" or count):
        return None
    budget = [_MAX_EVIDENCE]
    if not all(_valid_observation(observation, budget) for observation in observations):
        return None
    if not all(_valid_permission_observation(observation, budget) for observation in permission_observations):
        return None
    binding = cast(dict[str, object], value["binding"])
    typed_observations = cast(list[dict[str, object]], observations)
    typed_permissions = cast(list[dict[str, object]], permission_observations)
    if len({item["rule_id"] for item in typed_observations}) != len(typed_observations):
        return None
    if len({item["permission_id"] for item in typed_permissions}) != len(typed_permissions):
        return None
    uncertainty_count = sum(bool(item["uncertainty_reasons"]) for item in typed_observations + typed_permissions)
    uncertainty_count += error is not None
    if binding["observation_count"] != count or binding["uncertainty_count"] != uncertainty_count:
        return None
    canonical = json.dumps(
        {"observations": observations, "permission_observations": permission_observations, "evaluation_error": error},
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    ).encode("utf-8")
    expected = hashlib.sha256(b"hol-guard.native-command-observations.v1\0" + canonical).hexdigest()
    return cast(dict[str, object], value) if binding["observations_digest"] == expected else None

"""Publisher input observation and off-path policy compilation."""

from __future__ import annotations

import hashlib
import os
import platform
import sqlite3
import stat
from collections import OrderedDict
from contextlib import closing
from dataclasses import dataclass
from functools import partial
from pathlib import Path
from threading import Condition
from typing import TYPE_CHECKING, cast

from .config_source_io import (
    GUARD_CONFIG_FILENAMES,
    GuardConfigCapture,
    GuardConfigSourceError,
    capture_guard_config,
)
from .native_command_control_authority import AUTHORITY_FILE_NAME
from .native_command_control_binding import read_native_command_control_binding
from .native_policy_snapshot_codec import _digest_v3
from .native_policy_snapshot_constants import (
    NATIVE_POLICY_VERIFIER_KEY_NAME,
    NATIVE_RUNTIME_STATE_DIRECTORY,
    NativePolicySnapshotError,
)
from .native_policy_snapshot_policy import _merge_effective_native_policies, effective_native_policy_v3
from .native_policy_snapshot_resident_inputs import NativePolicySnapshotResidentInputsMixin

if TYPE_CHECKING:
    from .native_policy_snapshot_publisher import NativePolicySnapshotPublisher
    from .runtime.extension_control_runtime import ExtensionControlRuntime
    from .store import GuardStore


@dataclass(frozen=True)
class _CapturedPolicyInput:
    identity: object
    # None bypasses caching for a generic non-config input above the capture
    # limit. Guard TOML always uses the bounded source reader and raises instead.
    content: bytes | None


def _captured_config_reader(path: Path, *, inputs: dict[Path, _CapturedPolicyInput]) -> dict[str, object]:
    from .config import tomllib

    content = inputs[path].content
    if content is None:
        raise ValueError("uncaptured policy input")
    return cast(dict[str, object], tomllib.loads(content.decode("utf-8")))


class NativePolicySnapshotPublisherInputs(NativePolicySnapshotResidentInputsMixin):
    """Mixin containing filesystem observation outside synchronous hooks."""

    guard_home: Path  # pyright: ignore[reportUninitializedInstanceVariable]
    config_capture: GuardConfigCapture | None  # pyright: ignore[reportUninitializedInstanceVariable]
    store: GuardStore  # pyright: ignore[reportUninitializedInstanceVariable]
    _command_control_runtime: ExtensionControlRuntime | None  # pyright: ignore[reportUninitializedInstanceVariable]
    _condition: Condition  # pyright: ignore[reportUninitializedInstanceVariable]
    _acked: bool  # pyright: ignore[reportUninitializedInstanceVariable]
    _workspace_paths: set[Path]  # pyright: ignore[reportUninitializedInstanceVariable]
    _published_policy_fingerprint: tuple[str, str, str] | None  # pyright: ignore[reportUninitializedInstanceVariable]
    _observed_policy_fingerprint: tuple[str, str, str] | None  # pyright: ignore[reportUninitializedInstanceVariable]
    _compiled_workspace_policies: OrderedDict[Path | None, tuple[object, dict[str, object]]]  # pyright: ignore[reportUninitializedInstanceVariable]
    _database_policy_fingerprint: str | None  # pyright: ignore[reportUninitializedInstanceVariable]
    _cached_managed_identity: tuple[str, str | None, str | None, object]  # pyright: ignore[reportUninitializedInstanceVariable]

    def _current_input_fingerprint(
        self,
    ) -> tuple[tuple[tuple[str, tuple[int, int, int, int] | None], ...], tuple[tuple[str, int, int], ...]]:
        values: list[tuple[str, tuple[int, int, int, int] | None]] = []
        # The database and both journal modes are watched for cross-process
        # changes. WAL-only writes are included because they can contain an
        # effective policy mutation before checkpointing.
        paths = (
            self.guard_home / "config.toml",
            self.guard_home / "guard.db",
            self.guard_home / "guard.db-wal",
            self.guard_home / "guard.db-shm",
            self.guard_home / "guard.db-journal",
            self.guard_home / NATIVE_RUNTIME_STATE_DIRECTORY / NATIVE_POLICY_VERIFIER_KEY_NAME,
            self.guard_home / NATIVE_RUNTIME_STATE_DIRECTORY / AUTHORITY_FILE_NAME,
            *self._external_policy_paths(),
            *self._workspace_policy_paths(),
        )
        seen_paths: set[str] = set()
        for path in paths:
            path_key = str(path)
            if path_key in seen_paths:
                continue
            seen_paths.add(path_key)
            try:
                metadata = path.stat()
            except OSError:
                values.append((path_key, None))
            else:
                values.append(
                    (
                        path_key,
                        (metadata.st_mtime_ns, metadata.st_size, metadata.st_ino, metadata.st_ctime_ns),
                    )
                )
        return tuple(values), self._current_resident_fingerprint()

    def _workspace_policy_paths(self) -> tuple[Path, ...]:
        with self._condition:
            workspaces = tuple(self._workspace_paths)
        paths: list[Path] = []
        for workspace in workspaces:
            paths.extend(workspace / filename for filename in (".ai-plugin-scanner-guard.toml", ".hol-guard.toml"))
        return tuple(paths)

    def _compiled_effective_policy(self) -> dict[str, object]:
        """Build the native snapshot input off the synchronous hook path."""

        from .config import load_guard_config
        from .mdm.policy import _cache_path, load_managed_policy

        with self._condition:
            workspaces = tuple(sorted(self._workspace_paths, key=str))
        # Verify machine authority once per compilation pass, including HKLM on
        # Windows. Sharing this value does not cache a trust decision across
        # reconciliation passes or cause one cache write per workspace.
        managed = load_managed_policy(write_cache=False)
        managed_cache_path = _cache_path(platform.system())
        managed_identity = (
            managed.status,
            managed.policy.content_hash if managed.policy is not None else None,
            managed.reason_code,
            self._capture_policy_input(managed_cache_path).identity,
        )
        if managed.policy is not None and managed_identity != getattr(self, "_cached_managed_identity", None):
            # Retain the loader's durable last-known policy behavior, without
            # rewriting identical cache files on every reconciliation pass.
            managed = load_managed_policy()
            self._cached_managed_identity = (
                managed.status,
                managed.policy.content_hash if managed.policy is not None else None,
                managed.reason_code,
                self._capture_policy_input(managed_cache_path).identity,
            )
        home_path = self.guard_home / "config.toml"
        home_input = self._capture_config_policy_input(home_path)
        captured_inputs = {home_path: home_input.identity}
        common = (
            home_input.identity,
            managed.status,
            managed.policy.content_hash if managed.policy is not None else None,
            managed.reason_code,
        )
        if not hasattr(self, "_compiled_workspace_policies"):
            self._compiled_workspace_policies = OrderedDict()
        cache = self._compiled_workspace_policies
        policies: list[dict[str, object]] = []
        for workspace in (None, *workspaces):
            captured = {home_path: home_input}
            if workspace is not None:
                captured.update(
                    (workspace / name, self._capture_config_policy_input(workspace / name))
                    for name in (".ai-plugin-scanner-guard.toml", ".hol-guard.toml")
                )
            captured_inputs.update((path, value.identity) for path, value in captured.items())
            identity = (common, tuple((path, value.identity) for path, value in captured.items()))
            cacheable = all(value.content is not None for value in captured.values())
            cached = cache.get(workspace)
            if not cacheable or cached is None or cached[0] != identity:
                if cached is not None:
                    # Periodic reconciliation may discover a change with no
                    # file notification (for example HKLM). Withdraw authority
                    # before rebuilding that scope, just as the watcher does.
                    with self._condition:
                        self._acked = False
                        self._condition.notify_all()
                config = load_guard_config(
                    self.guard_home,
                    workspace=workspace,
                    managed_policy_state=managed,
                    config_reader=(
                        partial(_captured_config_reader, inputs=captured) if cacheable else self._uncached_config_reader
                    ),
                )
                policy = effective_native_policy_v3(config) | {"mode": config.mode}
                if cacheable:
                    cache[workspace] = (identity, policy)
                else:
                    cache.pop(workspace, None)
            else:
                policy = cached[1]
            if cacheable:
                cache.move_to_end(workspace)
            policies.append(policy)
        # Compiled entries are expendable; evicting one only requires rebuilding
        # it next pass. Registered active overlays are never evicted.
        while len(cache) > 1_025:
            cache.popitem(last=False)
        effective = _merge_effective_native_policies(tuple(policies))
        cast("NativePolicySnapshotPublisher", self)._compiled_config_inputs = captured_inputs
        return effective

    def _configuration_input_changed(self) -> bool:
        """Check bounded config captures without rebuilding policy or controls."""
        previous = cast("NativePolicySnapshotPublisher", self)._compiled_config_inputs
        if not previous:
            return False
        paths = (self.guard_home / "config.toml", *self._workspace_policy_paths())
        try:
            # A capture includes admitted source identity and a hash of the
            # exact bytes. Metadata equality cannot hide a changed overlay.
            return set(paths) != set(previous) or any(
                self._capture_config_policy_input(path).identity != previous[path] for path in paths
            )
        except (OSError, NativePolicySnapshotError, TypeError, ValueError, RuntimeError):
            with self._condition:
                self._acked = False
                self._condition.notify_all()
            return True

    def _capture_config_policy_input(self, path: Path) -> _CapturedPolicyInput:
        try:
            if self.config_capture is not None:
                captured = self.config_capture(path)
                return _CapturedPolicyInput(
                    (captured.identity, hashlib.sha256(captured.content).hexdigest()), captured.content
                )
            return self._capture_policy_input(path)
        except GuardConfigSourceError:
            # A rejected input may occur before cache-change invalidation.
            # Withdraw any previous ACK immediately, including during renewal;
            # generic publication errors can otherwise retain an unexpired ACK.
            with self._condition:
                self._acked = False
                self._condition.notify_all()
            raise

    def _uncached_config_reader(self, path: Path) -> dict[str, object]:
        return _captured_config_reader(path, inputs={path: self._capture_config_policy_input(path)})

    @staticmethod
    def _capture_policy_input(path: Path) -> _CapturedPolicyInput:
        if path.name in GUARD_CONFIG_FILENAMES:
            captured = capture_guard_config(path)
            return _CapturedPolicyInput(
                (captured.identity, hashlib.sha256(captured.content).hexdigest()), captured.content
            )
        try:
            entry = path.lstat()
            target = path.stat()
            if not stat.S_ISREG(target.st_mode):
                return _CapturedPolicyInput(("not-file", target.st_mode), b"")
            descriptor = os.open(path, os.O_RDONLY | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NONBLOCK", 0))
            with os.fdopen(descriptor, "rb") as handle:
                target = os.fstat(handle.fileno())
                if not stat.S_ISREG(target.st_mode):
                    return _CapturedPolicyInput(("not-file", target.st_mode), b"")
                content = handle.read(1024 * 1024 + 1)
        except OSError:
            # Preserve _read_toml's missing/inaccessible-file semantics. A later
            # successful read has a different content identity and is rebuilt.
            return _CapturedPolicyInput("unavailable", b"")
        metadata_identity = tuple(
            value
            for metadata in (entry, target)
            for value in (
                metadata.st_dev,
                metadata.st_ino,
                metadata.st_mode,
                metadata.st_uid,
                metadata.st_gid,
                metadata.st_size,
                metadata.st_mtime_ns,
                metadata.st_ctime_ns,
            )
        )
        if len(content) > 1024 * 1024:
            return _CapturedPolicyInput((metadata_identity, "uncached-large-input"), None)
        # Hash and parse these same captured bytes. Metadata-only caching is
        # insufficient on Windows, where ctime may represent creation time.
        return _CapturedPolicyInput((metadata_identity, hashlib.sha256(content).hexdigest()), content)

    def _database_policy_marker(self) -> str:
        """Read the publication authority domain through SQLite's WAL view.

        These bounded hashes are invalidation hints only. The publisher reads
        and authenticates full control authority before signing a binding.
        Receipts and activity rows cannot change this policy-domain marker.
        """

        path = (self.guard_home / "guard.db").absolute()
        try:
            with closing(sqlite3.connect(path.as_uri() + "?mode=ro", uri=True, timeout=0.05)) as connection:
                rows = connection.execute(
                    "select state_key, substr(cast(payload_json as blob), 1, 1048577) "
                    "from sync_state where state_key in ('policy_integrity', 'managed_controls_active', "
                    "'managed_controls_revision', 'managed_controls_manifest_context') order by state_key"
                ).fetchall()
                values: list[object] = [
                    (
                        key,
                        hashlib.sha256(payload).hexdigest()
                        if isinstance(payload, bytes) and len(payload) <= 1048576
                        else "invalid",
                    )
                    for key, payload in rows
                ]
                tables = {
                    row[0]
                    for row in connection.execute(
                        "select name from sqlite_master where type = 'table' and name in "
                        "('extension_control_authority_snapshot', 'extension_control_authority_transition')"
                    )
                }
                if "extension_control_authority_snapshot" in tables:
                    row = connection.execute(
                        "select substr(cast(revision as text), 1, 32), substr(catalog_digest, 1, 65), "
                        "substr(snapshot_digest, 1, 65), substr(snapshot_mac, 1, 65), "
                        "substr(cast(layers_json as blob), 1, 262145), "
                        "substr(cast(snapshot_json as blob), 1, 1048577) "
                        "from extension_control_authority_snapshot where singleton = 1"
                    ).fetchone()
                    values.append(
                        (
                            "local",
                            tuple(
                                hashlib.sha256(value).hexdigest() if isinstance(value, bytes) else value
                                for value in row
                            )
                            if row is not None
                            else None,
                        )
                    )
                if "extension_control_authority_transition" in tables:
                    row = connection.execute(
                        "select substr(cast(revision as text), 1, 32), substr(phase, 1, 32), "
                        "substr(snapshot_digest, 1, 65) from extension_control_authority_transition "
                        "order by revision desc limit 1"
                    ).fetchone()
                    values.append(
                        (
                            "transition",
                            tuple(
                                hashlib.sha256(value).hexdigest() if isinstance(value, bytes) else value
                                for value in row
                            )
                            if row is not None
                            else None,
                        )
                    )
            return _digest_v3(values)
        except (OSError, sqlite3.Error, ValueError, NativePolicySnapshotError):
            return "unavailable"

    def _compiled_command_extensions(self) -> dict[str, object]:
        try:
            binding, runtime = read_native_command_control_binding(
                self.store, getattr(self, "_command_control_runtime", None)
            )
            self._command_control_runtime = runtime
            return binding
        except (OSError, NativePolicySnapshotError, TypeError, ValueError, RuntimeError):
            with self._condition:
                self._acked = False
                self._condition.notify_all()
            raise

    @staticmethod
    def _external_policy_paths() -> tuple[Path, ...]:
        try:
            from .mdm.contracts import default_machine_paths

            machine_paths = default_machine_paths()
        except (OSError, RuntimeError, ValueError):
            return ()
        paths = [machine_paths.policy_path]
        paths.append(machine_paths.state_root / "managed-policy-cache.json")
        return tuple(path for path in paths if path is not None)

    def _policy_input_changed(self, changed_paths: set[str] | None = None) -> bool:
        """Compare effective policy in the publisher thread, never in hooks."""

        force_republish = False
        if not changed_paths:
            marker = self._database_policy_marker()
            previous_marker = self._database_policy_fingerprint
            self._database_policy_fingerprint = marker
            force_republish = previous_marker is not None and previous_marker != marker
            if force_republish:
                with self._condition:
                    self._acked = False
                    self._condition.notify_all()
        if changed_paths:
            database_paths = {
                str(self.guard_home / name) for name in ("guard.db", "guard.db-wal", "guard.db-shm", "guard.db-journal")
            }
            control_marker_path = str(self.guard_home / NATIVE_RUNTIME_STATE_DIRECTORY / AUTHORITY_FILE_NAME)
            # The publisher creates/commits this signed marker itself. Its
            # authoritative content is compared in the verified binding below;
            # treating its mtime as unconditional change would revoke every
            # first ACK. Changed/closed/invalid markers still change the binding
            # or fail verification, while an identical record needs no push.
            other_changed_paths = changed_paths - {control_marker_path}
            database_only_change = bool(other_changed_paths) and other_changed_paths <= database_paths
            if database_only_change:
                marker = self._database_policy_marker()
                previous_marker = getattr(self, "_database_policy_fingerprint", None)
                self._database_policy_fingerprint = marker
                if previous_marker == marker and control_marker_path not in changed_paths:
                    return False
                force_republish = previous_marker is not None and previous_marker != marker
            if other_changed_paths and not database_only_change:
                # Guard config, workspace overrides, MDM policy files, and
                # verifier state are effective-input boundaries. Republish before the
                # resident is used even when this Python projection cannot
                # yet express a workspace-specific native policy.
                force_republish = True
            if force_republish:
                # Revoke the old snapshot before potentially slow compilation.
                with self._condition:
                    self._acked = False
                    self._condition.notify_all()
        try:
            effective_policy = self._compiled_effective_policy()
            # ``_compiled_effective_policy`` carries the raw mode beside the
            # bounded policy so snapshot generation can derive enforce versus
            # observe. ``config_digest`` deliberately covers only the
            # bounded policy fields, however; comparing the whole mapping
            # would make every database heartbeat look like a policy change
            # and continuously revoke the ACKed snapshot.
            policy_for_digest = dict(effective_policy)
            policy_for_digest.pop("mode", None)
            current_fingerprint = (
                cast(str, _digest_v3(policy_for_digest)),
                cast(str, effective_policy["mode"]),
                _digest_v3(self._compiled_command_extensions()),
            )
        except (OSError, NativePolicySnapshotError, TypeError, ValueError, RuntimeError):
            current_fingerprint = ("unavailable", "", "")
        # Observation is independent of acknowledgment: unchanged inputs must
        # not reset a failed publication's retry backoff on every database write.
        previous_fingerprint = (
            self._observed_policy_fingerprint
            if self._observed_policy_fingerprint is not None
            else self._published_policy_fingerprint
        )
        self._observed_policy_fingerprint = current_fingerprint
        return force_republish or previous_fingerprint != current_fingerprint

    @staticmethod
    def _resolved_workspace(workspace: Path) -> Path:
        return workspace.expanduser().absolute()

"""Resident-generation observation helpers for native policy publication."""

from __future__ import annotations

import stat
from pathlib import Path

from .native_policy_snapshot_constants import NATIVE_RUNTIME_STATE_DIRECTORY


class NativePolicySnapshotResidentInputsMixin:
    """Observe resident generation state without reading policy payloads."""

    guard_home: Path  # pyright: ignore[reportUninitializedInstanceVariable]

    def _current_resident_fingerprint(self) -> tuple[tuple[str, int, int], ...]:
        """Observe resident generation metadata without policy/config reads."""

        resident_values: list[tuple[str, int, int]] = []
        state_dir = self.guard_home / NATIVE_RUNTIME_STATE_DIRECTORY
        try:
            resident_directories = sorted(
                (entry for entry in state_dir.iterdir() if entry.name.startswith("resident-v3-")),
                key=lambda entry: entry.name,
            )
        except OSError:
            resident_directories = []
        for directory in resident_directories:
            try:
                metadata = directory.stat()
            except OSError:
                continue
            resident_values.append((directory.name, metadata.st_mtime_ns, metadata.st_size))
            try:
                generation_files = sorted(
                    (entry for entry in directory.iterdir() if entry.name.startswith("generation-")),
                    key=lambda entry: entry.name,
                )
            except OSError:
                generation_files = []
            for entry in generation_files:
                try:
                    metadata = entry.stat()
                except OSError:
                    continue
                resident_values.append(
                    (
                        f"{directory.name}/{entry.name}",
                        metadata.st_mtime_ns,
                        metadata.st_size,
                    )
                )
        return tuple(resident_values)

    def _resident_directory_fingerprint(self) -> tuple[int, int] | None:
        """Read only the runtime-state directory metadata for the commit fence."""

        try:
            metadata = (self.guard_home / NATIVE_RUNTIME_STATE_DIRECTORY).lstat()
        except OSError:
            return None
        if not stat.S_ISDIR(metadata.st_mode):
            return None
        return metadata.st_mtime_ns, metadata.st_size

    def _resident_paths_match(self, observed: tuple[tuple[str, int, int], ...]) -> bool:
        """Recheck sampled resident paths without enumerating the directory."""

        state_dir = self.guard_home / NATIVE_RUNTIME_STATE_DIRECTORY
        for path_key, mtime_ns, size in observed:
            try:
                metadata = (state_dir / path_key).lstat()
            except OSError:
                return False
            if not stat.S_ISREG(metadata.st_mode) and not stat.S_ISDIR(metadata.st_mode):
                return False
            if metadata.st_mtime_ns != mtime_ns or metadata.st_size != size:
                return False
        return True

    def _confirm_resident_fingerprint(
        self,
        before: tuple[tuple[str, int, int], ...],
        observed: tuple[tuple[str, int, int], ...],
        resident_generation: int,
        observed_directory: tuple[int, int] | None,
    ) -> tuple[tuple[str, int, int], ...] | None:
        """Reject ACKs that do not identify the resident observed after push."""

        if before and before != observed:
            return None
        if not self._resident_fingerprint_matches_generation(observed, resident_generation):
            return None
        # Re-read only bounded metadata while the barrier is held. A changed
        # state-directory identity or sampled path means a resident restarted
        # after the full post-ACK sample; the stale ACK must not open readiness.
        if observed_directory is None:
            if observed:
                return None
        elif self._resident_directory_fingerprint() != observed_directory or not self._resident_paths_match(observed):
            return None
        return observed

    @staticmethod
    def _resident_fingerprint_matches_generation(
        fingerprint: tuple[tuple[str, int, int], ...],
        resident_generation: int,
    ) -> bool:
        """Require the ACK generation to be the newest observed resident."""

        generations: list[int] = []
        for path_key, _mtime_ns, _size in fingerprint:
            filename = path_key.rsplit("/", 1)[-1]
            if not filename.startswith("generation-") or not filename.endswith(".json"):
                continue
            raw_generation = filename[len("generation-") : -len(".json")]
            if not raw_generation.isdigit():
                return False
            generations.append(int(raw_generation))
        # Test doubles may acknowledge without materializing state files. A
        # real managed resident always publishes at least one generation file;
        # when files are present, an ACK for anything other than the newest
        # resident is definitively stale.
        return not generations or max(generations) == resident_generation

"""Authenticated records for the command-extension control authority."""

from __future__ import annotations

import hashlib
import hmac
import json
from dataclasses import dataclass
from enum import Enum
from typing import Final, cast

from .extension_control_contract import (
    CONTROL_SCHEMA_VERSION,
    ControlLayerKind,
    ControlState,
    ControlSurface,
    ControlTarget,
    ControlTargetKind,
    ExtensionControl,
    ExtensionControlLayer,
)

AUTHORITY_SCHEMA_VERSION: Final = 1
SNAPSHOT_PURPOSE: Final = "extension-control.snapshot"
TRANSITION_PURPOSE: Final = "extension-control.transition"
ANCHOR_PURPOSE: Final = "extension-control.anchor"
_AUTH_DOMAIN: Final = b"hol-guard.extension-control-authority.v1\0"


class ExtensionControlAuthorityError(RuntimeError):
    """An extension-control authority invariant could not be satisfied."""


class AuthorityPhase(str, Enum):
    PREPARED = "prepared"
    ANCHORED = "anchored"
    COMMITTED = "committed"


class AuthorityHealth(str, Enum):
    UNENROLLED = "unenrolled"
    PROTECTED = "protected"
    DEGRADED_UNACKNOWLEDGED = "degraded-unacknowledged"
    DEGRADED_ACKNOWLEDGED = "degraded-acknowledged"
    TAMPERED = "tampered"
    RECOVERY_REQUIRED = "recovery-required"


@dataclass(frozen=True, slots=True)
class ExtensionControlAuthorityView:
    health: AuthorityHealth
    revision: int
    catalog_digest: str
    layers: tuple[ExtensionControlLayer, ...]
    managed_revision: int = 0

    def layers_for(self, surface: ControlSurface) -> tuple[ExtensionControlLayer, ...]:
        if self.health is AuthorityHealth.PROTECTED:
            return self.layers
        if type(surface) is ControlSurface and surface in {
            ControlSurface.TRUSTED_LOCAL_RECOVERY,
            ControlSurface.TRUSTED_LOCAL_PROOF,
        }:
            return ()
        return (
            ExtensionControlLayer(
                schema_version=CONTROL_SCHEMA_VERSION,
                kind=ControlLayerKind.LOCAL_ADMIN,
                catalog_digest=self.catalog_digest,
                global_lockdown=True,
                controls=(),
            ),
        )


@dataclass(frozen=True, slots=True)
class AuthorityAnchor:
    revision: int
    snapshot_digest: str
    phase: AuthorityPhase


def layers_to_json(layers: tuple[ExtensionControlLayer, ...]) -> str:
    return _canonical_json([_layer_to_value(layer) for layer in layers])


def layers_from_json(value: str) -> tuple[ExtensionControlLayer, ...]:
    try:
        raw = cast(object, json.loads(value))
    except (TypeError, json.JSONDecodeError) as exc:
        raise ExtensionControlAuthorityError("invalid extension control layers") from exc
    if not isinstance(raw, list):
        raise ExtensionControlAuthorityError("invalid extension control layers")
    return tuple(_layer_from_value(item) for item in cast(list[object], raw))


def authenticated_record(
    payload: dict[str, object],
    *,
    key: bytes,
    purpose: str,
) -> tuple[str, str, str]:
    framed = {"authority_schema_version": AUTHORITY_SCHEMA_VERSION, "purpose": purpose, **payload}
    encoded = _canonical_json(framed)
    digest = hashlib.sha256(encoded.encode("utf-8")).hexdigest()
    mac = hmac.new(_purpose_key(key, purpose), encoded.encode("utf-8"), hashlib.sha256).hexdigest()
    return encoded, digest, mac


def verify_authenticated_record(
    encoded: str,
    *,
    expected_digest: str,
    expected_mac: str,
    key: bytes,
    purpose: str,
) -> dict[str, object]:
    try:
        raw = cast(object, json.loads(encoded))
    except (TypeError, json.JSONDecodeError) as exc:
        raise ExtensionControlAuthorityError("invalid authenticated authority record") from exc
    if not isinstance(raw, dict):
        raise ExtensionControlAuthorityError("invalid authenticated authority record")
    mapping = cast(dict[object, object], raw)
    if any(not isinstance(name, str) for name in mapping):
        raise ExtensionControlAuthorityError("invalid authenticated authority record")
    payload = cast(dict[str, object], mapping)
    if payload.get("authority_schema_version") != AUTHORITY_SCHEMA_VERSION:
        raise ExtensionControlAuthorityError("unsupported authority schema")
    if payload.get("purpose") != purpose:
        raise ExtensionControlAuthorityError("authority record purpose mismatch")
    canonical = _canonical_json(payload)
    actual_digest = hashlib.sha256(canonical.encode("utf-8")).hexdigest()
    actual_mac = hmac.new(_purpose_key(key, purpose), canonical.encode("utf-8"), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(actual_digest, expected_digest) or not hmac.compare_digest(actual_mac, expected_mac):
        raise ExtensionControlAuthorityError("authority record authentication failed")
    return payload


def anchor_to_json(anchor: AuthorityAnchor, *, key: bytes) -> str:
    encoded, digest, mac = authenticated_record(
        {
            "revision": anchor.revision,
            "snapshot_digest": anchor.snapshot_digest,
            "phase": anchor.phase.value,
        },
        key=key,
        purpose=ANCHOR_PURPOSE,
    )
    return _canonical_json({"record": encoded, "digest": digest, "mac": mac})


def anchor_from_json(value: str, *, key: bytes) -> AuthorityAnchor:
    try:
        raw_envelope = cast(object, json.loads(value))
    except (TypeError, json.JSONDecodeError) as exc:
        raise ExtensionControlAuthorityError("invalid authority anchor") from exc
    if not isinstance(raw_envelope, dict):
        raise ExtensionControlAuthorityError("invalid authority anchor")
    envelope = cast(dict[object, object], raw_envelope)
    record = envelope.get("record")
    digest = envelope.get("digest")
    mac = envelope.get("mac")
    if not all(isinstance(item, str) for item in (record, digest, mac)):
        raise ExtensionControlAuthorityError("invalid authority anchor")
    payload = verify_authenticated_record(
        cast(str, record),
        expected_digest=cast(str, digest),
        expected_mac=cast(str, mac),
        key=key,
        purpose=ANCHOR_PURPOSE,
    )
    revision = payload.get("revision")
    snapshot_digest = payload.get("snapshot_digest")
    phase = payload.get("phase")
    if type(revision) is not int or revision < 0:
        raise ExtensionControlAuthorityError("invalid authority anchor revision")
    if not isinstance(snapshot_digest, str) or len(snapshot_digest) != 64:
        raise ExtensionControlAuthorityError("invalid authority anchor digest")
    if not isinstance(phase, str):
        raise ExtensionControlAuthorityError("invalid authority anchor phase")
    try:
        parsed_phase = AuthorityPhase(phase)
    except ValueError as exc:
        raise ExtensionControlAuthorityError("invalid authority anchor phase") from exc
    return AuthorityAnchor(revision, snapshot_digest, parsed_phase)


def _layer_to_value(layer: ExtensionControlLayer) -> dict[str, object]:
    return {
        "schema_version": layer.schema_version,
        "kind": layer.kind.value,
        "catalog_digest": layer.catalog_digest,
        "global_lockdown": layer.global_lockdown,
        "controls": [
            {
                "target_kind": control.target.kind.value,
                "target_id": control.target.target_id,
                "state": control.state.value,
            }
            for control in layer.controls
        ],
    }


def _layer_from_value(raw: object) -> ExtensionControlLayer:
    if not isinstance(raw, dict):
        raise ExtensionControlAuthorityError("invalid extension control layer")
    mapping = cast(dict[object, object], raw)
    if any(not isinstance(name, str) for name in mapping):
        raise ExtensionControlAuthorityError("invalid extension control layer")
    value = cast(dict[str, object], mapping)
    controls_raw = value.get("controls")
    if not isinstance(controls_raw, list):
        raise ExtensionControlAuthorityError("invalid extension controls")
    controls: list[ExtensionControl] = []
    try:
        for item_raw in cast(list[object], controls_raw):
            if not isinstance(item_raw, dict):
                raise ExtensionControlAuthorityError("invalid extension control")
            item = cast(dict[str, object], item_raw)
            target_kind = ControlTargetKind(item.get("target_kind"))
            target_id = item.get("target_id")
            if not isinstance(target_id, str):
                raise ExtensionControlAuthorityError("invalid extension control target")
            controls.append(
                ExtensionControl(
                    ControlTarget(target_kind, target_id),
                    ControlState(item.get("state")),
                )
            )
        schema_version = value.get("schema_version")
        catalog_digest = value.get("catalog_digest")
        lockdown = value.get("global_lockdown")
        if not isinstance(schema_version, str) or not isinstance(catalog_digest, str):
            raise ExtensionControlAuthorityError("invalid extension control layer metadata")
        if type(lockdown) is not bool:
            raise ExtensionControlAuthorityError("invalid extension control lockdown")
        return ExtensionControlLayer(
            schema_version=schema_version,
            kind=ControlLayerKind(value.get("kind")),
            catalog_digest=catalog_digest,
            global_lockdown=lockdown,
            controls=tuple(controls),
        )
    except (TypeError, ValueError) as exc:
        raise ExtensionControlAuthorityError("invalid extension control layer") from exc


def _canonical_json(value: object) -> str:
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=True)


def _purpose_key(key: bytes, purpose: str) -> bytes:
    return hmac.new(key, _AUTH_DOMAIN + purpose.encode("utf-8"), hashlib.sha256).digest()

"""Implementation definitions reexported by the StoreBase facade."""

from __future__ import annotations

import hmac

from .store_base_definition import preserve_store_base_module as _preserve_module


@_preserve_module
def _is_approval_gate_one_shot_policy(row: sqlite3.Row) -> bool:
    return str(row["source"]) == _base._APPROVAL_GATE_POLICY_SOURCE and row["expires_at"] is not None


@_preserve_module
def _normalize_source_name(source: str | None) -> str:
    """Normalize a connection source name.

    The default source is 'default'. Source names are used to namespace
    OAuth credentials in the local store, allowing multiple simultaneous
    connections (e.g. production + staging).
    """
    if source is None:
        return "default"
    normalized = source.strip().lower()
    if not normalized:
        return "default"
    if not _base._SOURCE_NAME_PATTERN.match(normalized):
        raise ValueError(f"Invalid source name: {source!r}. Source names must match [a-zA-Z0-9][a-zA-Z0-9_-]*")
    if len(normalized) > 64:
        raise ValueError(f"Invalid source name: {source!r}. Source names must be 64 characters or fewer.")
    return normalized


@_preserve_module
def _oauth_sync_url_from_issuer(issuer: str) -> str:
    oauth_client = _base.resolve_guard_oauth_client_config(issuer)
    return f"{oauth_client.issuer}/api/guard/receipts/sync"


@_preserve_module
def _allowed_origin_from_sync_url(sync_url: str) -> str | None:
    parsed = _base.urlparse(sync_url)
    if not parsed.scheme or not parsed.netloc:
        return None
    return f"{parsed.scheme}://{parsed.netloc}"


@_preserve_module
def _secret_fingerprint(value: str) -> str:
    digest = _base.scrypt(
        value.encode("utf-8"),
        salt=_base._SECRET_FINGERPRINT_SALT,
        n=_base._SECRET_FINGERPRINT_N,
        r=_base._SECRET_FINGERPRINT_R,
        p=_base._SECRET_FINGERPRINT_P,
        dklen=_base._SECRET_FINGERPRINT_DKLEN,
    ).hex()
    return f"{_base._SECRET_FINGERPRINT_PREFIX}{digest}"


@_preserve_module
def _secret_matches_hash(value: str, expected_hash: str) -> bool:
    prefix = _base._SECRET_FINGERPRINT_PREFIX
    if (
        not expected_hash.startswith(prefix)
        or len(expected_hash) != len(prefix) + 2 * _base._SECRET_FINGERPRINT_DKLEN
        or any(character not in "0123456789abcdef" for character in expected_hash[len(prefix) :])
    ):
        return False
    return hmac.compare_digest(_base._secret_fingerprint(value), expected_hash)


@_preserve_module
def _should_warn_on_slow_store_transactions() -> bool:
    value = _base.os.environ.get(_base._SLOW_STORE_WARNING_ENV, "").strip().lower()
    return value in {"1", "true", "yes", "on"}


@_preserve_module
def receipt_index_statements() -> list[str]:
    return [
        ("create index if not exists idx_receipts_harness_artifact on runtime_receipts(harness, artifact_id)"),
        ("create index if not exists idx_receipts_timestamp_harness on runtime_receipts(timestamp, harness)"),
        ("create index if not exists idx_receipts_timestamp_desc on runtime_receipts(timestamp desc)"),
        ("create index if not exists idx_receipts_harness_timestamp_desc on runtime_receipts(harness, timestamp desc)"),
        (
            "create index if not exists idx_receipts_harness_artifact_timestamp_desc "
            "on runtime_receipts(harness, artifact_id, timestamp desc)"
        ),
        (
            "create index if not exists idx_receipts_approval_request_decision "
            "on runtime_receipts(approval_request_id, policy_decision)"
        ),
    ]


@_preserve_module
def _row_mapping(row: sqlite3.Row) -> dict[str, object]:
    keys = row.keys()
    return {key: row[key] for key in keys}


@_preserve_module
def _string_value(value: object) -> str | None:
    if isinstance(value, str) and value:
        return value
    return None


@_preserve_module
def _int_value(value: object) -> int | None:
    if isinstance(value, int) and not isinstance(value, bool):
        return value
    return None


@_preserve_module
def _mapping_int(payload: Mapping[str, object], key: str) -> int | None:
    return _base._int_value(payload.get(key))


@_preserve_module
def _parse_utc_timestamp(value: str) -> datetime:
    candidate = value.strip()
    if not candidate:
        raise ValueError("timestamp must not be empty")
    parsed = _base.datetime.fromisoformat(candidate.replace("Z", "+00:00"))
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=_base.timezone.utc)
    return parsed.astimezone(_base.timezone.utc)


@_preserve_module
def _canonical_utc_timestamp(value: str) -> str:
    """Normalize an ISO-8601 timestamp for safe storage and comparison."""

    return _base._parse_utc_timestamp(value).isoformat(timespec="microseconds")


@_preserve_module
def _timestamp_has_expired(expires_at: str, *, now: str) -> bool:
    """Return true at the expiry boundary and for malformed legacy values."""

    try:
        return _base._parse_utc_timestamp(expires_at) <= _base._parse_utc_timestamp(now)
    except (TypeError, ValueError):
        return True


@_preserve_module
def _now() -> str:
    return _base._canonical_utc_timestamp(_base.datetime.now(_base.timezone.utc).isoformat())


@_preserve_module
def _lease_expiry(now: str, lease_seconds: int) -> str:
    return (_base.datetime.fromisoformat(now) + _base.timedelta(seconds=max(lease_seconds, 1))).isoformat()


@_preserve_module
def _string_list(value: object) -> list[str]:
    if not isinstance(value, list):
        return []
    return [str(item) for item in value if isinstance(item, str) and item]


@_preserve_module
def _transport_value(value: object) -> TransportKind:
    if value == "local":
        return "local"
    if value == "remote":
        return "remote"
    if value == "hybrid":
        return "hybrid"
    return "local"


