            true,
        ),
        (json!({"tool_name": "kill"}), false),
    ] {
        let edge: GuardHookEdgeResultV2 = serde_json::from_slice(
            &crate::edge::evaluate_envelope_with_store(request(&root, &snapshot, payload), &store)
                .unwrap(),
